import { useState } from 'react'
import { Flag, Send } from 'lucide-react'
import { cx } from '../lib/utils'

const MAX_LEN = 800

/**
 * "Found a mistake?" report box — on every series page. Collapsed by
 * default; expands to a short form (what's wrong + optional chapter).
 * Anonymous reports are allowed; signed-in users are credited by
 * username. Stored server-side in Cloudflare R2 via /api/reports.
 */
export default function ReportBox({ seriesKey, seriesTitle }: { seriesKey: string; seriesTitle: string }) {
  const [open, setOpen] = useState(false)
  const [text, setText] = useState('')
  const [chapter, setChapter] = useState('')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [done, setDone] = useState(false)

  const submit = async () => {
    const clean = text.trim()
    if (clean.length < 5 || busy) return
    setBusy(true)
    setError('')
    try {
      const res = await fetch('/api/reports', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: 'series', key: seriesKey, text: clean, chapter: chapter.trim() || undefined }),
      })
      const data = await res.json().catch(() => ({}))
      if (!res.ok) {
        setError(data.error ?? 'Could not send the report — try again.')
        return
      }
      setDone(true)
      setText('')
      setChapter('')
    } catch {
      setError('Network error — try again.')
    } finally {
      setBusy(false)
    }
  }

  return (
    <section className="rounded-[18px] border border-line bg-paper p-6 sm:p-8">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="flex w-full items-center justify-between gap-3 text-left"
        aria-expanded={open}
      >
        <span className="flex items-center gap-2.5">
          <span className="grid h-9 w-9 shrink-0 place-items-center rounded-full bg-accent/10 text-accent">
            <Flag width={16} height={16} />
          </span>
          <span>
            <span className="block text-sm font-extrabold tracking-tight text-ink">Found a mistake?</span>
            <span className="mt-0.5 block text-xs text-ink-faint">
              Wrong chapter, broken image, bad info on “{seriesTitle}”? Tell us — reports go straight to the team.
            </span>
          </span>
        </span>
        <span className={cx('shrink-0 text-xs font-bold text-accent transition-transform', open && 'rotate-180')}>
          ▾
        </span>
      </button>

      {open && (
        <div className="mt-5 border-t border-line pt-5">
          {done ? (
            <div className="rounded-[12px] border border-emerald/30 bg-emerald/10 px-4 py-3.5 text-sm font-semibold text-emerald">
              Thanks — your report was recorded. The team will take a look.
            </div>
          ) : (
            <>
              <textarea
                value={text}
                onChange={(e) => setText(e.target.value.slice(0, MAX_LEN))}
                placeholder="What's wrong? e.g. Chapter 54 images won't load, the chapter number is wrong, the description is inaccurate…"
                rows={3}
                className="w-full resize-y rounded-[12px] border border-line-strong bg-paper px-4 py-3 text-sm text-ink outline-none transition-colors placeholder:text-ink-faint focus:border-accent"
              />
              <div className="mt-2 flex flex-wrap items-center justify-between gap-2">
                <input
                  value={chapter}
                  onChange={(e) => setChapter(e.target.value.replace(/[^0-9.\-]/g, '').slice(0, 12))}
                  placeholder="Chapter (optional)"
                  inputMode="text"
                  className="h-9 w-36 rounded-full border border-line-strong bg-paper px-3.5 text-xs font-semibold text-ink outline-none transition-colors placeholder:font-normal placeholder:text-ink-faint focus:border-accent"
                />
                <button
                  type="button"
                  onClick={submit}
                  disabled={busy || text.trim().length < 5}
                  className={cx(
                    'inline-flex items-center gap-2 rounded-full px-5 py-2 text-sm font-bold transition-all',
                    busy || text.trim().length < 5
                      ? 'cursor-not-allowed bg-ink/10 text-ink-faint'
                      : 'bg-accent text-white hover:bg-accent-dark',
                  )}
                >
                  <Send width={14} height={14} /> {busy ? 'Sending…' : 'Send Report'}
                </button>
              </div>
              <div className="mt-2 text-right text-xs text-ink-faint">{text.length}/{MAX_LEN}</div>
              {error && <p className="mt-2 text-xs font-semibold text-red-500">{error}</p>}
            </>
          )}
        </div>
      )}
    </section>
  )
}
