import { useMemo, useState, useEffect } from 'react'
import {
  Star, Eye, BookOpen, Share2, Bookmark, BookmarkCheck, CalendarDays, Search,
  ArrowLeft, User as UserIcon, Palette,
} from 'lucide-react'
import { readersAlsoEnjoyed } from '../lib/selectors'
import { useCatalog, useSeries } from '../lib/catalog-context'
import { useRealChapters, proxyImageUrl } from '../lib/mangadex'
import Cover from '../components/Cover'
import { SeriesCard } from '../components/SeriesCard'
import Comments from '../components/Comments'
import ReportBox from '../components/ReportBox'
import { StatusBadge, StarRating, Button, SectionHeader } from '../components/ui'
import { navigate } from '../lib/router'
import { slugify } from '../lib/utils'
import { useStore } from '../lib/store'
import { formatDate, formatViews, relativeDate, cx, chapterHref, seriesHref, genreHref, shortDescription, fullDescription, titleSlug, chapterTitleSuffix, firstChapterOf } from '../lib/utils'
import { setSeo, buildSeriesMeta } from '../lib/seo'
import posthog, { isPostHogEnabled } from '../lib/posthog'

export default function SeriesDetail({ slug }: { slug: string }) {
  const { series: catalog } = useCatalog()
  const { series, loading } = useSeries(slug)
  // §30: the hook unions the MD feed window with the MK twin's ground truth
  // (mkTwinSlug stamped by title collapse) — newest chapters never blank out.
  const { chapters: realChapters } = useRealChapters(series)
  const { inLibrary, toggleLibrary, progress, toast, ratings, rateChapter } = useStore()
  const [chapterQuery, setChapterQuery] = useState('')
  const [sortDesc, setSortDesc] = useState(true)

  // Unique per-series metadata (title, description, canonical, OG, JSON-LD)
  useEffect(() => {
    if (series) setSeo(buildSeriesMeta(series))
  }, [series?.id, series?.chapters?.length, series?.chapterCount])

  // Prefer the real MangaDex chapter list when this title is readable there
  // Union by chapter number (§29): a lagging MangaDex feed must never hide
  // newest chapters the catalog already serves — catalog entries fill gaps,
  // MD wins conflicts (carries mdChapterId for page loading).
  const chapterSource = useMemo(() => {
    if (!realChapters) return series?.chapters ?? []
    const byNumber = new Map(realChapters.map((c) => [c.number, c]))
    for (const c of series?.chapters ?? []) {
      if (!byNumber.has(c.number)) byNumber.set(c.number, c)
    }
    return [...byNumber.values()].sort((a, b) => a.number - b.number)
  }, [realChapters, series])

  const chapters = useMemo(() => {
    const list = [...chapterSource]
    list.sort((a, b) => (sortDesc ? b.number - a.number : a.number - b.number))
    const q = chapterQuery.trim().toLowerCase()
    if (!q) return list
    return list.filter(
      (c) => c.title.toLowerCase().includes(q) || String(c.number).includes(q),
    )
  }, [chapterSource, chapterQuery, sortDesc])

  if (loading) {
    return (
      <main className="mx-auto max-w-[1240px] px-4 py-16 sm:px-6 lg:px-8">
        <div className="h-64 animate-pulse rounded-[18px] bg-paper-3/60" />
        <div className="mt-8 grid gap-12 lg:grid-cols-[1fr_320px]">
          <div className="space-y-4">
            <div className="h-6 w-2/3 animate-pulse rounded bg-paper-3/60" />
            <div className="h-4 w-full animate-pulse rounded bg-paper-3/60" />
            <div className="h-4 w-5/6 animate-pulse rounded bg-paper-3/60" />
          </div>
          <div className="h-64 animate-pulse rounded-[16px] bg-paper-3/60" />
        </div>
      </main>
    )
  }

  if (!series) {
    return (
      <main className="mx-auto max-w-[1240px] px-4 py-24 text-center sm:px-6 lg:px-8">
        <h1 className="text-2xl font-extrabold">Series not found</h1>
        <p className="mt-2 text-ink-soft">The requested manhwa title may have been moved or unpublished.</p>
        <div className="mt-6"><Button onClick={() => navigate('/catalog')}>Back to Catalog</Button></div>
      </main>
    )
  }

  const saved = inLibrary(series.id)
  const prog = progress[series.id]
  const myRating = ratings[series.id]

  // rating a series also feeds the comment rank system (+5 XP, once per series)
  const rateWithXp = (v: number) => {
    if (isPostHogEnabled) posthog.capture('series_rated', { series_id: series.id, rating: v })
    rateChapter(series.id, v, false);
    void fetch('/api/comments', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'rate', seriesId: series.id }),
    }).catch(() => {});
  };
  // Blend the visitor's own rating into the displayed average — the catalog
  // rating stays the baseline; a personal rating shifts it as one extra vote.
  const displayRating = myRating
    ? (series.rating * series.ratingCount + myRating) / (series.ratingCount + 1)
    : series.rating
  const lastRead = prog ? chapterSource.find((c) => c.id === prog.chapterId) : undefined
  // next = the chapter AFTER the last-read one in reading order — chapter
  // numbers are source numbers now (gaps, 0, 5.5), so never number+1.
  // Deliberately NOT a useMemo: this sits after the early return, and a
  // hook here changes the hook count between renders (React error #310 —
  // the blank-page bug). Sorting per render is trivial.
  const sortedChapters = [...chapterSource].sort((a, b) => a.number - b.number)
  const lastReadIdx = lastRead ? sortedChapters.findIndex((c) => c.id === lastRead.id) : -1
  // Partial-window safety: before the per-series file loads, chapterSource
  // holds only the ~16 most recent chapters. A returning reader whose
  // progress predates that window (or a first-time visitor) must not be
  // sent to the window's oldest chapter — resume at the recorded chapter
  // number, or start at chapter 1 (firstChapter).
  const nextNumber = lastRead
    ? (sortedChapters[lastReadIdx + 1] ?? lastRead).number
    : prog?.chapterNumber ?? firstChapterOf(series)
  // True total: the trimmed window's length is NOT the chapter count
  const shownCount = series.chaptersPartial
    ? series.chapterCount ?? chapterSource.length
    : chapterSource.length
  const alsoEnjoyed = readersAlsoEnjoyed(catalog, series, 5)

  const share = async () => {
    const url = `${window.location.origin}${seriesHref(series)}`
    try {
      if (navigator.share) {
        await navigator.share({ title: series.title, text: shortDescription(series), url })
        if (isPostHogEnabled) posthog.capture('series_shared', { series_id: series.id, share_method: 'native' })
      } else {
        await navigator.clipboard.writeText(url)
        toast('Link copied to clipboard', 'accent')
        if (isPostHogEnabled) posthog.capture('series_shared', { series_id: series.id, share_method: 'clipboard' })
      }
    } catch {
      /* user dismissed */
    }
  }

  return (
    <main className="animate-fade-up">
      {/* Banner */}
      <div className="relative overflow-hidden border-b border-line">
        <div
          className="absolute inset-0"
          style={{
            background: `linear-gradient(120deg, hsl(${series.hue} 30% 12%) 0%, hsl(${series.hue} 24% 20%) 60%, hsl(${series.accentHue} 30% 30%) 100%)`,
          }}
        />
        {series.coverUrl && (
          <img
            src={proxyImageUrl(series.coverUrl)}
            alt=""
            aria-hidden
            className="absolute inset-0 h-full w-full object-cover opacity-25 blur-md"
          />
        )}
        <div
          className="absolute inset-0"
          style={{ background: 'linear-gradient(to top, rgba(24,24,23,0.92) 0%, rgba(24,24,23,0.25) 60%, transparent 100%)' }}
        />
        <div className="relative mx-auto max-w-[1240px] px-4 pb-10 pt-8 sm:px-6 lg:px-8">
          <button
            onClick={() => navigate('/catalog')}
            className="mb-8 inline-flex items-center gap-1.5 text-sm font-semibold text-white/70 transition-colors hover:text-white"
          >
            <ArrowLeft width={16} height={16} /> Back to Catalog
          </button>

          <div className="flex flex-col gap-8 sm:flex-row">
            <div className="h-[300px] w-[210px] shrink-0 self-start overflow-hidden rounded-[16px] shadow-2xl ring-1 ring-white/15 sm:h-[330px] sm:w-[230px]">
              <Cover series={series} rounded="rounded-none" priority />
            </div>

            <div className="min-w-0 flex-1 text-white">
              <div className="flex flex-wrap items-center gap-2.5">
                <StatusBadge status={series.status} />
                {series.staffPick && (
                  <span className="rounded-full bg-white/15 px-2.5 py-1 text-[11px] font-bold uppercase tracking-wide text-white backdrop-blur">
                    Staff Pick
                  </span>
                )}
                <span className="text-xs font-medium text-white/60">
                  New chapters every {series.schedule}
                </span>
              </div>

              <h1 className="mt-4 text-3xl font-extrabold leading-tight tracking-[-0.02em] text-white sm:text-4xl lg:text-5xl">
                {series.title}
              </h1>

              <div className="mt-4 flex flex-wrap gap-x-6 gap-y-2 text-sm text-white/70">
                <span className="inline-flex items-center gap-1.5">
                  <UserIcon width={15} height={15} /> Author:{' '}
                  {series.author && series.author !== 'Unknown' ? (
                    <a
                      href={`/author/${slugify(series.author)}`}
                      className="underline-offset-2 transition hover:text-white hover:underline"
                      onClick={(e) => {
                        e.preventDefault()
                        navigate(`/author/${slugify(series.author)}`)
                      }}
                    >
                      {series.author}
                    </a>
                  ) : (
                    series.author
                  )}
                </span>
                <span className="inline-flex items-center gap-1.5">
                  <Palette width={15} height={15} /> Artist: {series.artist}
                </span>
              </div>

              <div className="mt-5 flex flex-wrap items-center gap-x-5 gap-y-2 text-sm text-white/70">
                <span className="inline-flex items-center gap-1.5 font-bold text-white">
                  <Star width={15} height={15} className="fill-accent text-accent" />
                  {series.rating.toFixed(1)}
                  <span className="font-normal text-white/50">
                    ({formatViews(series.ratingCount)})
                  </span>
                </span>
                <span className="inline-flex items-center gap-2" title="Your rating — tap a star">
                  <span className="text-white/50">Rate:</span>
                  <StarRating
                    value={myRating ?? 0}
                    size={16}
                    onRate={(v) => rateWithXp(v)}
                  />
                </span>
                <span className="inline-flex items-center gap-1.5">
                  <Eye width={15} height={15} /> {formatViews(series.views)} readers
                </span>
                <span className="inline-flex items-center gap-1.5">
                  <BookOpen width={15} height={15} /> {shownCount} chapters
                </span>
                <span className="inline-flex items-center gap-1.5">
                  <CalendarDays width={15} height={15} /> Since {formatDate(series.firstReleased)}
                </span>
              </div>

              <div className="mt-5 flex flex-wrap gap-1.5">
                {series.genres.map((g) => (
                  <a
                    key={g}
                    href={genreHref(g)}
                    onClick={(e) => {
                      if (e.metaKey || e.ctrlKey) return
                      e.preventDefault()
                      navigate(genreHref(g))
                    }}
                    className="rounded-full border border-white/25 px-3 py-1 text-xs font-medium text-white/85 transition-colors hover:border-white hover:bg-white hover:text-ink"
                  >
                    {g}
                  </a>
                ))}
              </div>

              <div className="mt-7 flex flex-wrap gap-3">
                <Button
                  variant="accent"
                  size="lg"
                  href={chapterHref(series, nextNumber)}
                >
                  {lastRead ? `Continue Ch. ${nextNumber}` : 'Read First Chapter'}
                </Button>
                <Button
                  size="lg"
                  variant={saved ? 'accent' : 'outline'}
                  onClick={() => toggleLibrary(series.id, series.title)}
                  className={
                    saved
                      ? 'border border-accent-dark'
                      : 'border-white/30 text-white hover:border-white hover:bg-white hover:text-ink'
                  }
                  icon={saved ? <BookmarkCheck width={17} height={17} /> : <Bookmark width={17} height={17} />}
                >
                  {saved ? 'Saved to Library' : 'Save to Library'}
                </Button>
                <Button
                  size="lg"
                  variant="ghost"
                  onClick={share}
                  className="text-white/70 hover:bg-white/10 hover:text-white"
                  icon={<Share2 width={17} height={17} />}
                >
                  Share
                </Button>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="mx-auto max-w-[1240px] px-4 py-12 sm:px-6 lg:px-8">
        <div className="grid gap-12 lg:grid-cols-[1fr_320px]">
          {/* Left column */}
          <div>
            {/* Description */}
            <section>
              <div className="eyebrow mb-3 text-accent">Description</div>
              <p className="max-w-2xl whitespace-pre-line text-base leading-relaxed text-ink-soft">{fullDescription(series)}</p>
              <p className="mt-4 max-w-2xl text-base leading-relaxed text-ink-faint">
                {shownCount} chapters published
                to date, with the most recent release on {formatDate(series.lastUpdated)}.
              </p>
              <div className="mt-5 flex flex-wrap items-center gap-x-4 gap-y-2 rounded-[14px] border border-line bg-paper-2/60 px-4 py-3">
                <span className="text-sm font-bold">Rate this series:</span>
                <StarRating
                  value={myRating ?? 0}
                  size={22}
                  onRate={(v) => rateWithXp(v)}
                />
                <span className="text-xs text-ink-faint">
                  {myRating
                    ? `You rated it ${myRating} star${myRating > 1 ? 's' : ''} — thanks!`
                    : 'Tap a star to rate it (community average is shown above).'}
                </span>
              </div>
            </section>

            {/* Chapters */}
            <section className="mt-12">
              <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
                <div>
                  <div className="eyebrow mb-1.5 text-accent">All Issues</div>
                  <h2 className="text-2xl font-extrabold tracking-tight">Chapter list</h2>
                  <p className="mt-1.5 text-xs text-ink-faint">
                    {shownCount} chapters
                  </p>
                </div>
                <div className="flex items-center gap-2">
                  <div className="flex h-9 items-center gap-2 rounded-full border border-line-strong bg-paper px-3.5 focus-within:border-ink">
                    <Search width={14} height={14} className="text-ink-faint" />
                    <input
                      value={chapterQuery}
                      onChange={(e) => setChapterQuery(e.target.value)}
                      placeholder="Search chapters…"
                      className="w-36 bg-transparent text-sm outline-none placeholder:text-ink-faint sm:w-44"
                    />
                  </div>
                  <button
                    onClick={() => setSortDesc((v) => !v)}
                    className="h-9 rounded-full border border-line-strong bg-paper px-3.5 text-xs font-semibold text-ink-soft transition-colors hover:border-ink hover:text-ink"
                  >
                    {sortDesc ? 'Newest First' : 'Oldest First'}
                  </button>
                </div>
              </div>

              {chapterSource.length === 0 ? (
                <p className="rounded-[14px] border border-dashed border-line-strong bg-paper px-5 py-10 text-center text-sm text-ink-faint">
                  No chapters published yet
                </p>
              ) : (
                /* scrollable container — long series (600+ chapters) no
                   longer spread the whole page; capped height with the
                   site's thin scrollbar */
                <div className="thin-scroll max-h-[560px] overflow-y-auto overscroll-contain rounded-[16px] border border-line bg-paper">
                  {chapters.map((c, i) => {
                    const isRead = lastRead && c.number <= lastRead.number
                    const isCurrent = prog?.chapterId === c.id
                    return (
                      <a
                        key={c.id}
                        href={chapterHref(series, c.number)}
                        onClick={(e) => {
                          if (e.metaKey || e.ctrlKey) return
                          e.preventDefault()
                          if (isPostHogEnabled) {
                            posthog.capture('chapter_opened', {
                              series_id: series.id,
                              chapter_number: c.number,
                              entry_point: 'chapter_list',
                            })
                          }
                          navigate(chapterHref(series, c.number))
                        }}
                        className={cx(
                          'flex items-center gap-4 px-4 py-3.5 transition-colors hover:bg-ink/[0.035]',
                          i > 0 && 'border-t border-line',
                          isCurrent && 'bg-accent/[0.07]',
                        )}
                      >
                        <span
                          className={cx(
                            'w-12 shrink-0 text-sm font-bold tabular-nums',
                            isCurrent ? 'text-accent' : isRead ? 'text-ink-faint' : 'text-ink',
                          )}
                        >
                          {c.number}
                        </span>
                        <div className="min-w-0 flex-1">
                          {chapterTitleSuffix(c.title) && (
                            <div
                              className={cx(
                                'line-clamp-1 text-sm font-semibold',
                                isRead && !isCurrent && 'text-ink-soft',
                              )}
                            >
                              {chapterTitleSuffix(c.title)}
                            </div>
                          )}
                          <div className="mt-0.5 text-xs text-ink-faint">
                            {relativeDate(c.releaseDate)} · {c.pageCount} pages
                          </div>
                        </div>
                        {isCurrent ? (
                          <span className="shrink-0 rounded-full bg-accent px-2.5 py-1 text-[11px] font-bold uppercase tracking-wide text-white">
                            Reading
                          </span>
                        ) : isRead ? (
                          <span className="shrink-0 text-[11px] font-bold uppercase tracking-wide text-emerald">
                            Read
                          </span>
                        ) : (
                          <span className="shrink-0 text-xs font-semibold text-ink-faint transition-colors group-hover:text-accent">
                            Read →
                          </span>
                        )}
                      </a>
                    )
                  })}
                </div>
              )}
            </section>
          </div>

          {/* Right column */}
          <aside className="space-y-6">
            <div className="rounded-[16px] border border-line bg-paper p-5">
              <div className="eyebrow mb-3 text-ink-faint">Publisher</div>
              <dl className="space-y-3 text-sm">
                {[
                  ['Status', series.status],
                  ['Schedule', `Every ${series.schedule}`],
                  ['Chapters', String(shownCount)],
                  ['Debuted', formatDate(series.firstReleased)],
                  ['Last update', relativeDate(series.lastUpdated)],
                  ['Weekly readers', formatViews(series.weeklyViews)],
                ].map(([k, v]) => (
                  <div key={k} className="flex items-center justify-between gap-4">
                    <dt className="text-ink-faint">{k}</dt>
                    <dd className="font-semibold">{v}</dd>
                  </div>
                ))}
              </dl>
            </div>

            <div className="rounded-[16px] border border-line bg-paper p-5">
              <div className="eyebrow mb-3 text-ink-faint">Community Rating</div>
              <div className="flex items-center gap-3">
                <div className="text-3xl font-extrabold tabular-nums">{displayRating.toFixed(1)}</div>
                <div>
                  <StarRating value={displayRating} />
                  <div className="mt-1 text-xs text-ink-faint">
                    {formatViews(series.ratingCount + (myRating ? 1 : 0))} ratings
                  </div>
                </div>
              </div>
              <div className="mt-5 border-t border-line pt-4">
                <div className="eyebrow mb-2.5 text-ink-faint">Your Rating</div>
                <StarRating
                  value={myRating ?? 0}
                  size={22}
                  onRate={(v) => rateWithXp(v)}
                />
                <p className="mt-2 text-xs text-ink-faint">
                  {myRating
                    ? `You rated this ${myRating} star${myRating > 1 ? 's' : ''}.`
                    : 'Tap the stars to rate this series.'}
                </p>
              </div>
            </div>
          </aside>
        </div>

        {/* Readers also enjoyed */}
        {alsoEnjoyed.length > 0 && (
          <section className="mt-16">
            <SectionHeader eyebrow="Similar Series" title="Readers Also Enjoyed" />
            <div className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 lg:grid-cols-5">
              {alsoEnjoyed.map((s) => (
                <SeriesCard key={s.id} series={s} />
              ))}
            </div>
          </section>
        )}

        {/* Comments */}
        <section className="mt-16">
          <Comments type="series" threadKey={titleSlug(series)} heading="Comments" />
        </section>

        {/* Found a mistake? — anonymous-friendly report box (stored in R2) */}
        <section className="mt-6">
          <ReportBox seriesKey={titleSlug(series)} seriesTitle={series.title} />
        </section>
      </div>
    </main>
  )
}
